<template><div><div class="page-heading"><div><div class="eyebrow-label">{{sectionCode}}</div><h1>{{title}}</h1><p>{{description}}</p></div><el-button v-if="mode==='tasks'" type="primary" @click="dialog=true"><el-icon><Plus/></el-icon> 新建航拍任务</el-button></div>
<template v-if="mode==='tasks'"><div class="grid stats"><div v-for="m in taskStats" class="panel"><span class="muted">{{m.name}}</span><div class="metric">{{m.value}}</div><span class="muted">{{m.note}}</span></div></div><div class="panel" style="margin-top:17px"><div class="toolbar"><el-input v-model="keyword" placeholder="搜索任务名称 / 区域" clearable style="width:280px"><template #prefix><el-icon><Search/></el-icon></template></el-input><el-radio-group v-model="statusFilter" @change="loadTasks(1)"><el-radio-button label="全部"/><el-radio-button label="处理中"/><el-radio-button label="已完成"/><el-radio-button label="排队中"/></el-radio-group><el-button type="primary" plain @click="loadTasks(1)">查询</el-button></div><el-table :data="tasks" stripe><el-table-column prop="name" label="任务名称" min-width="220"><template #default="s"><div class="task-name"><span class="task-pulse" :class="s.row.status==='已完成'?'done':''"></span><b>{{s.row.name}}</b></div></template></el-table-column><el-table-column prop="region" label="作业区域"/><el-table-column label="作业区坐标" width="190"><template #default="s"><span v-if="s.row.latitude!=null&&s.row.longitude!=null">{{Number(s.row.latitude).toFixed(4)}}, {{Number(s.row.longitude).toFixed(4)}}</span><span v-else class="muted">未录入</span></template></el-table-column><el-table-column label="解译算法"><template #default="s">{{algorithmLabel(s.row.algorithm)}}</template></el-table-column><el-table-column label="创建时间"><template #default="s">{{formatTime(s.row.createdAt)}}</template></el-table-column><el-table-column prop="status" label="状态"><template #default="s"><el-tag :type="statusType(s.row.status)" effect="dark">{{s.row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="340"><template #default="s"><el-button link type="primary" :disabled="s.row.status==='PROCESSING'" @click="run(s.row)">开始解译</el-button><el-button link @click="openUpload(s.row)">上传影像</el-button><el-button link @click="preview(s.row)">预览</el-button><el-button link @click="openDetail(s.row)">详情</el-button><el-button link type="danger" @click="removeTask(s.row)">删除</el-button></template></el-table-column></el-table><div class="toolbar" style="justify-content:flex-end;margin-top:15px"><el-pagination :current-page="taskQuery.page" :page-size="taskQuery.size" :total="taskQuery.total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @current-change="loadTasks" @size-change="changeTaskSize"/></div></div></template>
<template v-else-if="mode==='images'"><div class="grid two"><div class="panel"><div class="panel-title"><b>影像入库</b><span class="muted">TIFF / GeoTIFF / JPG / PNG</span></div><div class="upload-zone" @click="$refs.file.click()" @dragover.prevent @drop.prevent="dropFile"><el-icon><UploadFilled/></el-icon><h3>拖拽影像到此处，或点击选择</h3><p class="muted">原始影像仅保存到磁盘，数据库只记录元数据与路径</p><el-button type="primary" plain>选择本地文件</el-button><input ref="file" type="file" hidden accept=".tif,.tiff,.jpg,.jpeg,.png" @change="selectFile"></div><div v-if="selectedFile" class="selected-file"><el-icon><Document/></el-icon><div><b>{{selectedFile.name}}</b><span>{{formatSize(selectedFile.size)}}</span></div><el-button link type="danger" @click="selectedFile=null">移除</el-button></div></div><div class="panel"><div class="panel-title"><b>上传配置</b><el-tag type="success" effect="dark">LOCAL STORAGE</el-tag></div><el-form label-position="top"><el-form-item label="关联任务"><el-select v-model="uploadTask" placeholder="选择一个任务" style="width:100%"><el-option v-for="t in tasks" :key="t.id" :label="t.name" :value="t.id"/></el-select></el-form-item><el-form-item label="数据说明"><el-input type="textarea" :rows="4" placeholder="记录航线、采集时间、坐标系等信息"/></el-form-item><el-button type="primary" :disabled="!selectedFile||!uploadTask" @click="upload">上传并入库</el-button></el-form></div></div><div class="panel" style="margin-top:17px"><div class="panel-title"><b>该任务已入库影像</b><span class="muted">可以逐张解译，也可以在任务页选择多张一起解译</span></div><el-table :data="taskImages" stripe><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="fileName" label="文件名" min-width="220"/><el-table-column prop="filePath" label="磁盘路径" min-width="320" show-overflow-tooltip/><el-table-column prop="fileSize" label="大小" width="120"><template #default="s">{{formatSize(s.row.fileSize)}}</template></el-table-column><el-table-column prop="createdAt" label="入库时间" width="180"/><el-table-column label="操作" width="180"><template #default="s"><el-button link type="primary" :loading="submitting" @click="runSingleImage(s.row)">解译此图</el-button><el-button link type="danger" @click="removeImage(s.row)">删除</el-button></template></el-table-column></el-table><el-button style="margin-top:14px" @click="loadTaskImages" :disabled="!uploadTask">刷新列表</el-button></div></template>
<template v-else-if="mode==='algorithms'"><div class="grid" style="grid-template-columns:minmax(280px,600px)"><div v-for="a in algorithmsView" :key="a.key" class="panel algorithm-card" @click="chooseAlgorithm(a)"><div class="algorithm-icon">{{a.icon}}</div><h3>{{a.name}}</h3><p class="muted">{{a.description}}</p><div class="algorithm-foot"><span>{{a.detail}}</span><el-tag :type="a.ready?'success':'warning'" effect="dark">{{a.status}}</el-tag></div></div></div><div class="panel" style="margin-top:17px"><div class="panel-title"><b>C2FNet 使用说明</b></div><el-alert title="上传一张影像后启动伪装目标检测。模型未就绪时，请先检查权重和推理服务。" type="info" :closable="false" show-icon/><p class="muted">结果为与原图同尺寸的灰度响应图：越亮表示模型对前景的响应越强，不代表经过校准的概率。航拍影像的实际效果需单独验证。</p></div></template>
<template v-else-if="mode==='results'"><div class="grid two"><div class="panel result-preview"><img v-if="previewUrl" :key="selectedResult.id" :src="previewUrl" alt="解译结果预览" style="width:100%;height:100%;min-height:0;object-fit:contain"/><template v-else><el-icon><PictureFilled/></el-icon><div class="preview-label">暂无可预览的解译结果</div></template></div><div class="panel"><div class="panel-title"><b>解译结果详情</b><el-tag :type="selectedResult&&selectedResult.status==='SUCCESS'?'success':'info'" effect="dark">{{selectedResult?selectedResult.status:'NO DATA'}}</el-tag></div><el-form label-position="top"><el-form-item label="选择图片结果"><el-select :model-value="selectedResult?.id" placeholder="选择要预览的结果" style="width:100%" @change="selectResultId"><el-option v-for="r in previewOptions" :key="r.id" :value="r.id" :label="'#'+r.id+' · '+imageName(r.sourcePath)+' · '+r.status"/></el-select></el-form-item></el-form><div class="toolbar" style="margin-bottom:14px"><el-button :disabled="!canPreviousResult" @click="stepResult(-1)">上一张</el-button><el-button :disabled="!canNextResult" @click="stepResult(1)">下一张</el-button><span class="muted">{{selectedResult?imageName(selectedResult.sourcePath):'暂无结果'}}</span></div><div class="detail-list"><div><span>解译算法</span><b>{{algorithmLabel(selectedResult&&selectedResult.algorithm)}}</b></div><div><span>输入影像</span><b class="path">{{selectedResult?selectedResult.sourcePath:'—'}}</b></div><div><span>完成时间</span><b>{{selectedResult?selectedResult.createdAt:'—'}}</b></div><div><span>结果路径</span><b class="path">{{selectedResult?selectedResult.maskPath:'—'}}</b></div></div><el-button type="primary" style="margin-top:25px" :disabled="!selectedResult||selectedResult.status!=='SUCCESS'" @click="downloadMask"><el-icon><Download/></el-icon> 下载 TIFF</el-button><el-button style="margin-top:25px;margin-left:10px" @click="loadResults">刷新</el-button></div></div><div class="panel" style="margin-top:17px"><div class="panel-title"><b>历史解译记录</b><span class="muted">{{results.length}} / {{resultQuery.total}} 条 · 点击行查看预览</span></div><div class="toolbar"><el-select v-model="resultAlgorithm" clearable placeholder="按算法筛选" style="width:190px"><el-option v-for="a in algorithmOptions" :key="a.value" :label="a.label" :value="a.value"/></el-select><el-select v-model="resultStatus" clearable placeholder="按状态筛选" style="width:150px"><el-option label="成功" value="SUCCESS"/><el-option label="失败" value="FAILED"/><el-option label="运行中" value="RUNNING"/></el-select><el-button @click="loadResults">刷新</el-button><el-tag v-if="resultTaskId" closable @close="showAllResults">任务 #{{resultTaskId}}</el-tag></div><el-table :data="results" row-key="id" :current-row-key="selectedResult?.id" stripe highlight-current-row @row-click="selectResult"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="algorithm" label="解译算法" min-width="210"><template #default="s">{{algorithmLabel(s.row.algorithm)}}</template></el-table-column><el-table-column prop="sourcePath" label="输入影像" min-width="240" show-overflow-tooltip><template #default="s"><span :title="s.row.sourcePath">{{imageName(s.row.sourcePath)}}</span></template></el-table-column><el-table-column prop="status" label="状态" width="120"><template #default="s"><el-tag :type="s.row.status==='SUCCESS'?'success':s.row.status==='FAILED'?'danger':'warning'" effect="dark">{{s.row.status}}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="时间" width="180"/><el-table-column label="操作" width="170"><template #default="s"><el-button link type="primary" @click.stop="selectResult(s.row)">预览此图</el-button><el-button link type="danger" @click.stop="removeResult(s.row)">删除</el-button></template></el-table-column></el-table><div class="toolbar" style="justify-content:flex-end;margin-top:15px"><el-pagination :current-page="resultQuery.page" :page-size="resultQuery.size" :total="resultQuery.total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @current-change="loadResults" @size-change="changeResultSize"/></div></div></template>
<template v-else><div class="panel"><div class="panel-title"><b>可导出成果</b><span class="muted">{{readyExports}} / {{exportItems.length}} 个文件就绪</span><div style="display:flex;gap:10px"><el-button link type="primary" @click="loadExports">刷新</el-button><el-button type="primary" plain :disabled="!readyExports" @click="downloadAllExports">打包下载全部</el-button></div></div><el-table :data="exportItems" stripe><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="taskName" label="所属任务" min-width="170"/><el-table-column prop="algorithmLabel" label="解译算法" width="140"/><el-table-column prop="maskPath" label="成果路径" min-width="300" show-overflow-tooltip/><el-table-column label="文件大小" width="130"><template #default="s">{{s.row.ready?formatSize(s.row.maskSize):'文件已缺失'}}</template></el-table-column><el-table-column prop="createdAt" label="完成时间" width="180"/><el-table-column label="操作" width="160"><template #default="s"><el-button link type="primary" :disabled="!s.row.ready" @click="downloadExport(s.row)">下载 ZIP</el-button><el-button link :disabled="!s.row.previewExists" @click="openPreview(s.row)">预览</el-button></template></el-table-column></el-table><div v-if="!exportItems.length" class="muted" style="padding:12px 0">暂无成功解译成果，先到「航拍任务」启动一次解译</div></div></template>
<el-dialog v-model="runDialog" title="选择要解译的图片" width="650px"><template v-if="runTask"><p>{{runTask.name}} · 已选择 {{selectedImageIds.length}} / {{runImages.length}} 张</p><div class="toolbar"><el-button @click="selectedImageIds=runImages.map(image=>image.id)">全选</el-button><el-button @click="selectedImageIds=[]">清空</el-button></div><el-checkbox-group v-model="selectedImageIds"><div v-for="image in runImages" :key="image.id" style="padding:8px 0"><el-checkbox :value="image.id">{{image.fileName}}</el-checkbox></div></el-checkbox-group><p class="muted">每张图片生成独立结果。解译完成后可在结果中心切换预览。</p></template><template #footer><el-button @click="runDialog=false">取消</el-button><el-button type="primary" :loading="submitting" :disabled="!selectedImageIds.length" @click="submitSelectedImages">解译所选图片</el-button></template></el-dialog><el-drawer v-model="detailOpen" :title="detail&&detail.task?detail.task.name:'任务详情'" size="640px"><div v-if="detail"><div class="panel-title"><b>任务信息</b><el-tag effect="dark">{{detail.task.status}}</el-tag></div><div class="detail-list"><div><span>作业区域</span><b>{{detail.task.region||'—'}}</b></div><div><span>解译算法</span><b>{{algorithmLabel(detail.task.algorithm)}}</b></div><div><span>创建时间</span><b>{{detail.task.createdAt}}</b></div></div><div class="panel-title" style="margin-top:18px"><b>已入库影像（{{detail.images.length}}）</b></div><el-table :data="detail.images" size="small"><el-table-column prop="id" label="ID" width="60"/><el-table-column prop="fileName" label="文件名" min-width="180"/><el-table-column prop="filePath" label="磁盘路径" min-width="240" show-overflow-tooltip/></el-table><div class="panel-title" style="margin-top:18px"><b>解译记录（{{detail.interpretations.length}}）</b></div><el-table :data="detail.interpretations" size="small"><el-table-column prop="id" label="ID" width="60"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="maskPath" label="结果路径" min-width="240" show-overflow-tooltip/><el-table-column prop="createdAt" label="时间" width="170"/></el-table></div></el-drawer><el-dialog v-model="dialog" title="新建航拍任务" width="480px"><el-form :model="form" label-position="top"><el-form-item label="任务名称"><el-input v-model="form.name" placeholder="例如：华东农田巡检-002"/></el-form-item><el-form-item label="作业区域"><el-input v-model="form.region" placeholder="省 / 市 / 区域名称"/></el-form-item><el-form-item label="默认解译算法"><el-select v-model="form.algorithm" style="width:100%"><el-option label="伪装目标检测" value="camouflaged_object_detection"/></el-select></el-form-item><el-form-item label="作业区坐标（可选，用于监测态势图定位）"><div style="display:flex;gap:8px"><el-input v-model.number="form.latitude" placeholder="纬度，如 31.2304"/><el-input v-model.number="form.longitude" placeholder="经度，如 121.4737"/></div></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">创建任务</el-button></template></el-dialog></div></template>
<script setup>import{computed,ref,onMounted,onBeforeUnmount,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{Plus,Search,UploadFilled,Document,PictureFilled,Download,DocumentChecked}from'@element-plus/icons-vue';import{taskApi,imageApi,interpretationApi,algorithmApi,exportApi,dashboardApi}from'../api/http';import{imageName,selectVisibleResult,resultOptions}from'../utils/interpretation';const route=useRoute(),dialog=ref(false),tasks=ref([]),keyword=ref(''),statusFilter=ref('全部'),selectedFile=ref(null),uploadTask=ref(null),form=ref({name:'',region:'',algorithm:'camouflaged_object_detection',latitude:null,longitude:null});const mode=computed(()=>route.path.slice(1)||'dashboard'),titles={tasks:['MISSION CONTROL','航拍任务管理','规划任务、上传影像并启动异步解译'],images:['IMAGERY HUB','遥感影像上传','建立原始影像与任务之间的可追溯关系'],algorithms:['AI ENGINES','智能解译算法','统一的模型服务协议，方便接入真实推理引擎'],results:['RESULTS CENTER','解译结果预览','查看掩码、统计数据与空间成果'],exports:['DELIVERY CENTER','成果导出下载','将已完成成果交付给业务人员']};const title=computed(()=>titles[mode.value]?.[1]||'平台模块'),sectionCode=computed(()=>titles[mode.value]?.[0]||'PLATFORM'),description=computed(()=>titles[mode.value]?.[2]||''),taskStats=ref([{name:'全部任务',value:'—',note:'累计创建'},{name:'处理中',value:'—',note:'AI 推理中'},{name:'已完成',value:'—',note:'成功归档'},{name:'成功率',value:'—',note:'成功任务占比'}]),algorithms=[{key:'camouflaged_object_detection',icon:'◌',name:'伪装目标检测',description:'识别复杂背景中的低对比度、弱特征目标。',status:'UNKNOWN'}];const taskQuery=ref({page:1,size:10,total:0,pages:0});
const resultQuery=ref({page:1,size:10,total:0,pages:0});
const runDialog=ref(false),runTask=ref(null),runImages=ref([]),selectedImageIds=ref([]),submitting=ref(false);
const resultTaskId=computed(()=>Number(route.query.taskId)||undefined);
let resultRequest=0,refreshTimer,pinnedResultId=null;
const TASK_STATUS={'处理中':'PROCESSING','已完成':'COMPLETED','排队中':'QUEUED'};
async function loadTasks(page=1){try{const data=await taskApi.page({page,size:taskQuery.value.size,keyword:keyword.value||undefined,status:TASK_STATUS[statusFilter.value]||undefined});tasks.value=data.items||[];taskQuery.value={page:data.page,size:data.size,total:data.total,pages:data.pages}}catch{tasks.value=[]}}
function changeTaskSize(size){taskQuery.value.size=size;loadTasks(1)}
const router=useRouter(),results=ref([]),selectedResult=ref(null),taskImages=ref([]),algorithmStatus=ref([]);
const algorithmNames={camouflaged_object_detection:'伪装目标检测'};
function algorithmLabel(key){return algorithmNames[key]||key||'—'}
const previewUrl=computed(()=>selectedResult.value&&selectedResult.value.status==='SUCCESS'?interpretationApi.previewUrl(selectedResult.value.id):null);
const algorithmsView=computed(()=>algorithms.map(a=>{const hit=algorithmStatus.value.find(x=>x.algorithm===a.key);if(!hit)return{...a,detail:'等待推理服务返回状态',status:'UNKNOWN',ready:false};return{...a,detail:(hit.weights_ready?'权重已就绪':'权重缺失或加载失败')+' · '+(hit.model||''),status:hit.runtime_ready?(hit.weights_ready?'READY':'NO WEIGHTS'):'OFFLINE',ready:!!hit.runtime_ready&&!!hit.weights_ready}}));
const previewOptions=computed(()=>resultOptions(results.value,selectedResult.value));
const currentResultIndex=computed(()=>results.value.findIndex(item=>item.id===selectedResult.value?.id));
const canPreviousResult=computed(()=>currentResultIndex.value>0||resultQuery.value.page>1);
const canNextResult=computed(()=>currentResultIndex.value>=0&&(currentResultIndex.value<results.value.length-1||resultQuery.value.page<resultQuery.value.pages));
function selectResult(row){pinnedResultId=null;selectedResult.value=row}
function selectResultId(id){selectResult(previewOptions.value.find(item=>item.id===id)||null)}
async function stepResult(offset){
  const index=currentResultIndex.value+offset;
  if(index>=0&&index<results.value.length){selectResult(results.value[index]);return}
  const page=resultQuery.value.page+offset;
  if(page<1||page>resultQuery.value.pages)return;
  await loadResultPage(page);
  selectResult(offset>0?results.value[0]:results.value.at(-1));
}
function showAllResults(){router.push({path:'/results'})}
function downloadMask(){if(selectedResult.value)window.open(interpretationApi.maskUrl(selectedResult.value.id))}
async function loadResults(page=1){return loadResultPage(page,undefined,true)}
async function loadAlgorithms(){try{const data=await algorithmApi.list();algorithmStatus.value=data.algorithms||[]}catch{algorithmStatus.value=[]}}
async function loadTaskImages(){if(!uploadTask.value){taskImages.value=[];return}try{taskImages.value=await imageApi.list(uploadTask.value)}catch{taskImages.value=[]}}
watch(uploadTask,loadTaskImages);
const detailOpen=ref(false),detail=ref(null),exportItems=ref([]),resultAlgorithm=ref(''),resultStatus=ref('');
watch([resultAlgorithm,resultStatus],()=>loadResultPage(1));
const algorithmOptions=[{value:'camouflaged_object_detection',label:'伪装目标检测'}];
async function loadResultPage(page=1,preferredId,keepPinned=false){
  const request=++resultRequest;
  const safePage=typeof page==='number'?page:1;
  if(!keepPinned)pinnedResultId=null;
  const requestedId=preferredId??(keepPinned?pinnedResultId:null);
  try{
    const data=await interpretationApi.page({page:safePage,size:resultQuery.value.size,taskId:resultTaskId.value,status:resultStatus.value||undefined,algorithm:resultAlgorithm.value||undefined});
    if(request!==resultRequest)return;
    results.value=data.items||[];
    resultQuery.value={page:data.page,size:data.size,total:data.total,pages:data.pages};
    selectedResult.value=selectVisibleResult(results.value,requestedId??selectedResult.value?.id);
    if(requestedId&&!results.value.some(item=>String(item.id)===String(requestedId))){
      const requested=await interpretationApi.get(requestedId);
      if(request===resultRequest&&(!resultTaskId.value||requested.taskId===resultTaskId.value)){
        selectedResult.value=requested;pinnedResultId=requested.id;
      }
    }
  }catch(e){if(request===resultRequest){results.value=[];selectedResult.value=null}}
}
function changeResultSize(size){resultQuery.value.size=size;loadResultPage(1)}
const readyExports=computed(()=>exportItems.value.filter(e=>e.ready).length);
async function loadExports(){try{exportItems.value=await exportApi.list()}catch{exportItems.value=[]}}
async function loadTaskStats(){try{const s=await dashboardApi.summary();taskStats.value[0].value=s.totalTasks;taskStats.value[1].value=s.processingTasks+s.queuedTasks;taskStats.value[2].value=s.completedTasks;taskStats.value[3].value=s.successRate+'%'}catch{}}
function downloadExport(row){window.open(exportApi.packageUrl(row.id))}
function downloadAllExports(){window.open(exportApi.packageAllUrl())}
function openPreview(row){router.push({path:'/results',query:{taskId:row.taskId,resultId:row.id}})}
async function openDetail(row){try{detail.value=await taskApi.detail(row.id);detailOpen.value=true}catch(e){ElMessage.error(e?.response?.data?.message||'任务详情加载失败')}}
async function removeTask(row){try{await ElMessageBox.confirm(`删除任务「${row.name}」会同时删除其影像与解译记录，确认删除？`,'删除任务',{type:'warning'})}catch{return}try{await taskApi.remove(row.id);tasks.value=tasks.value.filter(t=>t.id!==row.id);await Promise.all([loadResults(),loadExports()]);ElMessage.success('任务已删除')}catch(e){ElMessage.error(e?.response?.data?.message||'删除失败')}}
async function removeImage(row){try{await ElMessageBox.confirm(`确认删除影像「${row.fileName}」及其磁盘文件？`,'删除影像',{type:'warning'})}catch{return}try{await imageApi.remove(uploadTask.value,row.id);await loadTaskImages();ElMessage.success('影像已删除')}catch(e){ElMessage.error(e?.response?.data?.message||'删除失败')}}
async function removeResult(row){try{await ElMessageBox.confirm('确认删除该解译记录及结果文件？','删除解译记录',{type:'warning'})}catch{return}try{await interpretationApi.remove(row.id);if(selectedResult.value&&selectedResult.value.id===row.id)selectedResult.value=null;await Promise.all([loadResults(),loadExports()]);ElMessage.success('解译记录已删除')}catch(e){ElMessage.error(e?.response?.data?.message||'删除失败')}}onMounted(()=>{
  loadTasks(1);loadAlgorithms();loadExports();loadTaskStats();
  refreshTimer=setInterval(()=>{if(mode.value==='results')loadResultPage(resultQuery.value.page,undefined,true)},3000);
});
onBeforeUnmount(()=>{clearInterval(refreshTimer);resultRequest++});
watch(()=>[route.path,route.query.taskId,route.query.resultId],()=>{
  if(mode.value==='results'){selectedResult.value=null;loadResultPage(1,route.query.resultId)}
  if(mode.value==='algorithms')loadAlgorithms();
  if(mode.value==='exports')loadExports();
  if(mode.value==='tasks'){loadTasks(1);loadTaskStats()}
},{immediate:true});
function statusType(s){return s==='COMPLETED'?'success':s==='PROCESSING'?'warning':s==='FAILED'?'danger':'info'}async function create(){if(!form.value.name||!form.value.region)return ElMessage.warning('请填写任务名称和区域');try{const result=await taskApi.create(form.value);tasks.value.unshift(result)}catch(e){ElMessage.error(e?.response?.data?.message||'任务创建失败');return}dialog.value=false;form.value={name:'',region:'',algorithm:'camouflaged_object_detection',latitude:null,longitude:null};ElMessage.success('任务创建成功')}async function run(row){
  try{
    const images=await imageApi.list(row.id);
    if(!images.length){ElMessage.warning('该任务还没有影像，请先上传');return}
    runTask.value=row;runImages.value=images;selectedImageIds.value=images.map(image=>image.id);runDialog.value=true;
  }catch(e){ElMessage.error(e?.response?.data?.message||'影像列表加载失败')}
}
async function submitImages(task,ids){
  if(submitting.value)return false;
  submitting.value=true;
  try{
    const response=await taskApi.run(task.id,task.algorithm,{image_ids:ids});
    task.status='PROCESSING';runDialog.value=false;
    ElMessage.success('已提交 '+response.imageCount+' 张图片，每张图片会单独生成结果');
    await router.push({path:'/results',query:{taskId:task.id}});
    await loadResultPage(1);
    return true;
  }catch(e){ElMessage.error(e?.response?.data?.message||'解译提交失败');return false}
  finally{submitting.value=false}
}
async function submitSelectedImages(){if(selectedImageIds.value.length)await submitImages(runTask.value,[...selectedImageIds.value])}
async function runSingleImage(image){
  try{
    const task=tasks.value.find(item=>item.id===uploadTask.value)||await taskApi.get(uploadTask.value);
    await submitImages(task,[image.id]);
  }catch(e){ElMessage.error(e?.response?.data?.message||'关联任务加载失败')}
}
function preview(row){router.push({path:'/results',query:{taskId:row.id}})}
function openUpload(row){uploadTask.value=row.id;loadTaskImages();router.push('/images');ElMessage.info('已选择任务，请上传影像')}function selectFile(e){selectedFile.value=e.target.files[0]}function dropFile(e){selectedFile.value=e.dataTransfer.files[0]}function formatSize(n){return n>=0?(n/1024/1024).toFixed(2)+' MB':'—'}
function chooseAlgorithm(a){if(!a.ready){ElMessage.warning('C2FNet 尚未就绪，请检查权重和推理服务');return}router.push('/tasks')}
function formatTime(v){return v?String(v).replace('T',' ').slice(0,19):'—'}async function upload(){if(!uploadTask.value)return ElMessage.warning('请先选择关联任务');try{await imageApi.upload(uploadTask.value,selectedFile.value);selectedFile.value=null;await loadTaskImages();ElMessage.success('影像上传成功')}catch(e){ElMessage.error(e?.response?.data?.message||'影像上传失败')}}</script>

